#ifdef PHOTON_CLOUD_CONSUMER_GUARD
#if defined WORLD_OVERWORLD
    // Keep gather and implicit-LOD lightning sampling outside pixel-varying flow.
    float clouds_apparent_distance =
        min_of(textureGather(colortex12, refracted_uv * taau_render_scale, 0));
    float clouds_ambient_scattering = 0.0;
    if (LIGHTNING_FLASH_UNIFORM > 0.01) {
        clouds_ambient_scattering =
            texture(colortex12, refracted_uv * taau_render_scale).z;
    }

    if (is_translucent || is_translucent_lod) {
        if (clouds_apparent_distance < view_distance) {
            // Only this consumer needs age/filter math and explicit-LOD color.
            float pixel_age = texelFetch(
                colortex12,
                ivec2(refracted_uv * view_res * taau_render_scale),
                0
            ).y;
            float ld = 2.0 * dampen(max0(1.0 - 0.1 * pixel_age));
            vec4 clouds_and_aurora =
                textureLod(colortex11, refracted_uv * taau_render_scale, ld);
            if (LIGHTNING_FLASH_UNIFORM > 0.01) {
                clouds_and_aurora.xyz +=
                    LIGHTNING_FLASH_UNIFORM * lightning_flash_intensity *
                    clouds_ambient_scattering;
            }
            clouds_and_aurora.xyz *= clamp01(1.0 - blindness - darknessFactor);
            fragment_color =
                fragment_color * clouds_and_aurora.w + clouds_and_aurora.xyz;
        }
    }
#endif
#else
